import type { MetadataRoute } from "next";
import { siteUrl } from "@/config/site";

/**
 * robots.txt — allow everything except internal API routes, and point crawlers
 * at the sitemap. Generated by Next at `/robots.txt`.
 */
export default function robots(): MetadataRoute.Robots {
  return {
    rules: [
      {
        userAgent: "*",
        allow: "/",
        disallow: ["/api/"],
      },
    ],
    sitemap: `${siteUrl}/sitemap.xml`,
    host: siteUrl,
  };
}
